	@Test
	void closingPoolLeavesBorrowedConnectionOpenUntilReturned() throws Exception {
		Repository repository = mock(Repository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		when(repository.getConnection()).thenReturn(connection);
		when(connection.getRepository()).thenReturn(repository);
		PooledRepositoryConnectionFactory pool = new PooledRepositoryConnectionFactory(
				new DirectRepositoryConnectionFactory(repository));
		try {
			RepositoryConnection borrowed = pool.getConnection();
			try {
				pool.destroy();
				verify(connection, never()).close();
			} finally {
				borrowed.close();
			}
			verify(connection).close();
		} finally {
			pool.destroy();
		}
	}

